/** Contratos visuais de planos, apoio, camadas e baú, sem recalibrar o combate. */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { ToyRoomArenaBuilder } from '../../../../src/js/toy-room/ToyRoomArenaBuilder.js';
import { createToyRoomInitialEntities } from '../../../../src/js/toy-room/ToyRoomInitialEntities.js';
import { renderArenaEnvironment, renderArenaTemple } from '../../../../src/js/toy-room/ArenaEnvironment.js';
import { renderBattle } from '../../../../src/js/toy-room/BattleRenderer.js';
import { ToyRoomBattle } from '../../../../src/js/toy-room/ToyRoomBattle.js';
import { arenaHUDLayout } from '../../../../src/js/toy-room/ArenaHUD.js';
import { ArenaCamera } from '../../../../src/js/toy-room/ArenaCamera.js';
import { calculateMobileUILayout } from '../../../../src/js/ui/MobileUILayout.js';
const entities=createToyRoomInitialEntities(),before=structuredClone(entities);
const arena=new ToyRoomArenaBuilder().build(entities);assert.deepEqual(entities,before,'Composição não altera o mundo da exploração');
assert.equal(arena.ground,690);assert.ok(arena.structures.every(s=>s.footY>arena.wallBase));
assert.deepEqual(arena.structures.map(s=>s.footY),arena.structures.map(s=>s.footY).sort((a,b)=>a-b));
const inventory=JSON.parse(fs.readFileSync('docs/sprites/inventario.json')).items;
const images=new Map();for(const item of inventory)for(const key of item.aliases||[])if(item.width&&item.height)images.set(key,{key,width:item.width,height:item.height});
const draws=[],order=[];let patterns=0,clips=0,m={a:1,d:1,e:0,f:0},stack=[];
const ctx=new Proxy({save(){stack.push({...m});},restore(){m=stack.pop();},translate(x,y){m.e+=x*m.a;m.f+=y*m.d;},scale(x,y){m.a*=x;m.d*=y;},createPattern(){patterns++;return {};},clip(){clips++;},createLinearGradient(){return {addColorStop(){}};},createRadialGradient(){return {addColorStop(){}};},drawImage(image,...args){const [x,y,w,h]=args.length===8?args.slice(4):args;draws.push({key:image.key,x:m.e+m.a*x,y:m.f+m.d*y,w:w*m.a,h:h*m.d});order.push(image.key);}},{get:(o,k)=>k in o?o[k]:()=>{}});
const room={...entities,assets:{get:k=>images.get(k)},environmentFloorTile:{width:186,height:48},environmentChest:images.get('toy-room-chest-brinquedos-v1'),environmentTable:{key:'table',width:137,height:119}};
renderArenaEnvironment(ctx,room,arena);renderArenaEnvironment(ctx,room,arena);assert.equal(patterns,1,'Padrão de piso reutilizado por contexto');
const rect=key=>draws.find(d=>d.key===key),window=rect('toy-room-window-curtains-v1');
for(const key of ['toy-room-oak-cabinet-v1','toy-room-bookshelf-v1','toy-room-rocking-horse-v1']){
 const d=rect(key);assert.ok(d,'Arte consumida: '+key);
 assert.ok(d.x+d.w<=window.x||d.x>=window.x+window.w||d.y>=window.y+window.h||d.y+d.h<=window.y,'Janela livre: '+key);
 assert.ok(order.indexOf('toy-room-oval-rug-v1')<order.indexOf(key),'Tapete abaixo do móvel');
}
for(const [id,key] of [['wardrobe','toy-room-oak-cabinet-v1'],['bookshelf','toy-room-bookshelf-v1'],['rocking-horse','toy-room-rocking-horse-v1'],['toy-chest','toy-room-chest-brinquedos-v1']])assert.ok(Math.abs(rect(key).y+rect(key).h-arena.structures.find(s=>s.sourceId===id).footY)<1e-8,'Apoio da imagem: '+id);
const rug=rect('toy-room-oval-rug-v1'),source=images.get(rug.key);assert.ok(Math.abs(rug.h/rug.w-source.height/source.width*arena.floorProjection)<1e-10,'Tapete e piso compartilham projeção');
renderArenaTemple(ctx,room,arena,true);assert.ok(clips>0);
const actor={actor:'bear',x:1120,facing:-1,state:'IDLE',elapsed:0};
const battle={room:{...room,ctx,canvas:{width:960,height:540,clientWidth:960},player:{x:430}},state:{mode:'BATTLE',enemy:actor,index:0,jump:0},tuning:{ground:690},ready:true,error:null,
 presentation:{renderBackground(){order.push('background');},renderForeground(){order.push('foreground');},renderPlayer(){order.push('player');},renderHUD(){order.push('hud');}},enemyPose:()=> 'Idle',manifest:{actors:{bear:{animations:{Idle:{frames:[{file:'bear',anchor:{x:20,y:80},width:100,height:100,displayScale:1}]}}}}},images:new Map([['bear',{key:'enemy'}]])};
renderBattle(battle);assert.ok(order.indexOf('enemy')<order.indexOf('foreground'));assert.ok(order.indexOf('foreground')<order.indexOf('player'),'Foreground também executa com renderer próprio da menina');
const transport={room:entities,state:{transition:{elapsed:0,incoming:actor,outgoing:actor}},arenaChest:ToyRoomBattle.prototype.arenaChest,presentation:{transportOrigin:()=>arena.transportOrigin}};
const origin=ToyRoomBattle.prototype.transitionPlacement.call(transport,true);assert.equal(origin.x,arena.transportOrigin.x);assert.equal(origin.y,arena.transportOrigin.y);
transport.presentation=null;const legacy=ToyRoomBattle.prototype.transitionPlacement.call(transport,true);assert.equal(legacy.x,1335);assert.equal(legacy.y,610,'Legado preservado');
for(const [w,h]of [[1280,720],[390,844],[844,390]]){
 const layout=calculateMobileUILayout({}, {left:0,right:w,top:0,bottom:h},1,w<1000),hud=arenaHUDLayout(layout);
 assert.ok(hud.labelY-15>56,'Texto abaixo dos botões DOM');
 for(const jump of [0,150,300])for(const [x,enemyX]of [[210,620],[430,1120],[970,1270]]){
  const camera=new ArenaCamera(),player={x},enemy={...actor,x:enemyX};for(let i=0;i<100;i++)camera.update(1,player,enemy,jump);
  const frame=camera.frame(layout,{player,mobilePresentation:w<1000},{enemy,jump});
  assert.ok(frame.envelope.left*frame.scale+frame.ox>=frame.left-1);assert.ok(frame.envelope.right*frame.scale+frame.ox<=frame.right+1);
  assert.ok(frame.envelope.top*frame.scale+frame.oy>=frame.top-1);assert.ok(690*frame.scale+frame.oy<=frame.bottom+1);
 }
}
console.log('Composição aprovada: janela livre, apoios e camadas, projeção, foreground real, origem do baú/legado, HUD e 27 enquadramentos.');
